import assert from "node:assert/strict";
import { test } from "node:test";
import { existsSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const profileRoot = join(here, "data", "profiles", "phase22-golden-nasa");
const app = readFileSync(join(here, "app.js"), "utf8");

// The golden profile is generated by scripts/build_phase22_golden_case.py and is not
// tracked in git, so a clean checkout skips the profile checks instead of failing.
const published = existsSync(join(profileRoot, "manifest.json"));

test("phase 2.2 golden profile is published and internally consistent", {
  skip: published ? false : "frontend/app/data/profiles/phase22-golden-nasa not published (run scripts/build_phase22_golden_case.py)",
}, () => {
  const manifest = JSON.parse(readFileSync(join(profileRoot, "manifest.json"), "utf8"));
  const runConfig = JSON.parse(readFileSync(join(profileRoot, "run_config.json"), "utf8"));
  const scenario = JSON.parse(readFileSync(join(profileRoot, "battery_dashboard_nasa.json"), "utf8"));
  const predictions = JSON.parse(readFileSync(join(profileRoot, "prediction_records.json"), "utf8"));
  const contributions = JSON.parse(readFileSync(join(profileRoot, "metric_contributions.json"), "utf8"));
  const curveRefs = JSON.parse(readFileSync(join(profileRoot, "curve_segment_refs.json"), "utf8"));

  assert.equal(manifest.kind, "phase22_golden");
  assert.equal(runConfig.target_excluded_from_predictor, true);
  assert.equal(runConfig.held_out_key, "nasa/B0018");
  assert.match(runConfig.model_artifact_id, /^model@sha256:[0-9a-f]{64}$/);
  assert.match(runConfig.dataset_snapshot_id, /^dataset-snapshot@sha256:[0-9a-f]{64}$/);
  assert.match(runConfig.split_assignment_id, /^protocol@sha256:[0-9a-f]{64}$/);
  assert.equal(predictions.records.length, 102);
  assert.equal(contributions.records.length, predictions.records.length);
  assert.equal(curveRefs.records.length, predictions.records.length);
  assert.equal(scenario.points.length, predictions.records.length);
  assert.equal(curveRefs.records.every((row) => row.availability === "available"), true);
  assert.ok(Math.abs(
    contributions.records.reduce((total, row) => total + row.mae_contribution, 0) -
    scenario.metrics.mae
  ) <= Number.EPSILON);
});

test("app.js wires the phase 2.2 golden case", () => {
  assert.match(app, /DATA\?\.profileManifest\?\.kind === "phase22_golden"/);
  assert.match(app, /metric_contributions\.json/);
  assert.match(app, /真实黄金案例/);
  assert.match(app, /MAE 贡献/);
  assert.match(app, /const viewMatchesPinnedCase = evidenceViewMatchesPinnedCase\(\)/);
  assert.match(app, /cycle: context\.cycle \?\? selection\.cycle_id/);
  assert.match(app, /"已固定" : "待固定"/);
  assert.match(app, /已签署案例不可原位改写；请创建新案例版本/);
  assert.match(app, /创建新案例版本以固定/);
});
